import csv
import re

def parse_grade(grade_str):
    if not grade_str:
        return ''
    m = re.search(r'\(([PJH]\d)\)', grade_str)
    if m:
        return m.group(1)
    grade_map = {
        '小四': 'P4', '小五': 'P5', '小六': 'P6',
        '國一': 'J1', '國二': 'J2', '國三': 'J3',
        '高一': 'H1', '高二': 'H2', '高三': 'H3',
    }
    for k, v in grade_map.items():
        if k in grade_str:
            return v
    return ''

def get_best_phone(row):
    for idx in [7, 8, 9]:
        if idx < len(row):
            raw = row[idx].strip()
            phone = re.sub(r'\D', '', raw)
            if phone and 8 <= len(phone) <= 11:
                return phone
    if len(row) > 6:
        raw = row[6].strip()
        phone = re.sub(r'\D', '', raw)
        if phone and 6 <= len(phone) <= 12:
            return phone
    return ''

skip_names = {'姓名', '學生', '學生姓名', ''}

students = []
current_grade = ''

with open('/home/admin/學籍資料表 - 系統匯入.csv', 'r', encoding='utf-8-sig') as f:
    rows = list(csv.reader(f))

for i, row in enumerate(rows):
    if i < 2:
        continue
    if not row or all(c.strip() == '' for c in row):
        continue

    grade_str = row[0].strip() if row else ''
    name = row[3].strip() if len(row) > 3 else ''

    g = parse_grade(grade_str)
    if g:
        current_grade = g

    if not name or name in skip_names:
        continue

    skip_patterns = ['年級', '畢業', '科目數', '總計', '占比', '大學', '高中科', '國中科', '國小科']
    if any(p in name for p in skip_patterns):
        continue

    school = row[2].strip() if len(row) > 2 else ''
    phone = get_best_phone(row)

    # Check 停課日期 (col 18) - valid date like 113/6/5
    stop_date = row[18].strip() if len(row) > 18 else ''
    is_stopped = bool(re.match(r'^\d{2,3}/\d{1,2}/\d{1,2}$', stop_date))

    if is_stopped:
        continue  # Skip stopped students

    students.append({
        'grade': current_grade,
        'name': name,
        'school': school,
        'phone': phone,
    })

# Write clean CSV for import
with open('/tmp/donhu_students_clean.csv', 'w', newline='', encoding='utf-8') as f:
    writer = csv.writer(f)
    writer.writerow(['年級', '姓名', '學校', '電話'])
    for s in students:
        writer.writerow([s['grade'], s['name'], s['school'], s['phone']])

print(f"Generated {len(students)} students to /tmp/donhu_students_clean.csv")
print("\nFirst 10 rows:")
for s in students[:10]:
    print(f"  {s['grade']}\t{s['name']}\t{s['school']}\t{s['phone']}")
EOF
